def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if isinstance(params, dict):
			out_params = {f":{key}": value for key, value in params.items()}
			for key in out_params:
				sql = sql.replace(f":{key[1:]}", key)
		else:
			out_params = [f":{i}" for i in range(1, len(params) + 1)]
			for i, param in enumerate(out_params):
				sql = sql.replace(f"%s", param, 1)
		return sql, out_params

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		# Assuming in-style parameters are using '%' and out-style parameters are using ':'
		if isinstance(params, dict):
			# Named parameters
			out_params = dict(params)
			for key in params:
				sql = sql.replace(f"%({key})s", f":{key}")
		else:
			# Ordinal parameters
			out_params = list(params)
			sql = re.sub(r'%s', lambda m: f":{m.group(0).count('%')}", sql)
		return sql, out_params

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		out_style_params = []
		converted_sql = sql
		if isinstance(params, Mapping):
			for i, (key, value) in enumerate(params.items()):
				converted_sql = converted_sql.replace(f":{key}", f"${i+1}")
				out_style_params.append(value)
