def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    result = []

    lines = text.split('\n')
    for line in lines:
        if line.strip().startswith('```'):
            code_block = not code_block
        if not code_block:
            match = re.finditer(r'(?<!\w)(#\w+)(?!\w)', line)
            for m in match:
                tag = m.group(0)
                tags.add(tag)
                if replacer:
                    line = line[:m.start()] + replacer(tag) + line[m.end():]
        result.append(line)

    return tags, '\n'.join(result)

